INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','easy','flashcard','What toxin produced by Staphylococcus aureus causes Toxic Shock Syndrome?','["TSST-1 (Toxic Shock Syndrome Toxin-1) — a superantigen that non-specifically activates up to 20% of all T-cells by cross-linking MHC class II with T-cell receptors outside the normal antigen-binding groove, causing a massive cytokine storm"]','A','Distinguish: TSST-1 causes menstrual TSS (tampon-associated); staphylococcal enterotoxins (SEA-SEE) cause food poisoning TSS. Both are superantigens. Treatment: fluids, antistaphylococcal antibiotics, and IVIG in severe cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','easy','flashcard','What do the exfoliative toxins A and B of S. aureus do and what disease do they cause?','["Exfoliatin A and B are serine proteases that cleave desmoglein-1 (a desmosomal adhesion protein), disrupting keratinocyte adhesion — causing staphylococcal scalded skin syndrome (SSSS) in neonates and bullous impetigo in localised infection"]','A','Desmoglein-1 is also the target of autoantibodies in pemphigus foliaceus. Intraepidermal splitting occurs at the granular layer with no inflammation. SSSS resolves without scarring. Adults rarely affected due to rapid renal clearance of circulating toxin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','easy','flashcard','What is the mechanism by which MRSA resists beta-lactam antibiotics?','["The mecA gene (carried on the SCCmec mobile genetic element) encodes PBP2a, an alternative transpeptidase with very low affinity for ALL beta-lactams (penicillins, cephalosporins, carbapenems), allowing cell-wall peptidoglycan synthesis to continue in their presence"]','A','Vancomycin bypasses PBP2a by binding D-Ala-D-Ala dipeptide precursors directly. CA-MRSA strains often also carry Panton-Valentine leukocidin (PVL) gene, associated with necrotising skin and soft-tissue infections and severe pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','medium','flashcard','What is the role of M protein in Streptococcus pyogenes virulence?','["M protein is a major surface antigen and virulence factor that inhibits complement activation (binds factor H and fibrinogen, blocking C3b deposition) and phagocytosis; type-specific antibodies against M protein confer immunity but >80 serotypes prevent broad protection"]','A','M protein shares structural epitopes with cardiac myosin, tropomyosin, and sarcolemmal proteins — the structural basis of molecular mimicry that drives rheumatic fever carditis. The M protein gene (emm) is used for molecular epidemiological typing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','medium','flashcard','What is molecular mimicry and how does it explain rheumatic fever?','["Molecular mimicry: antibodies against S. pyogenes M protein cross-react with structurally similar host cardiac proteins (myosin, tropomyosin, sarcolemma) causing autoimmune inflammation of the heart valves and myocardium — particularly the mitral and aortic valves"]','A','Rheumatic fever follows pharyngeal (never skin) GAS infection. Jones criteria: major (carditis, migratory polyarthritis, Sydenham''''s chorea, erythema marginatum, subcutaneous nodules) and minor (fever, elevated CRP/ESR, prolonged PR interval). Penicillin V prophylaxis prevents recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','medium','flashcard','What unique intracellular motility mechanism does Listeria monocytogenes use to spread between cells?','["Listeria uses its ActA surface protein to recruit the host Arp2/3 complex, polymerising actin behind the bacterium into ''''actin rocket tails'''' that propel it through the cytoplasm and directly into adjacent cells — evading extracellular antibodies and complement"]','A','Listeriolysin O (LLO, a cholesterol-dependent cytolysin) escapes the phagosome, enabling cytoplasmic access. Listeria grows at 4°C (''''cold enrichment''''), making refrigerated deli meats, soft cheeses, and smoked fish vehicles for infection. Ampicillin is treatment of choice (cephalosporins — NOT effective against Listeria).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','medium','flashcard','Who are the highest-risk groups for severe Listeria monocytogenes infection?','["Pregnant women (amnionitis, stillbirth, neonatal sepsis with ''''granulomatosis infantiseptica''''), neonates, elderly >60, and immunocompromised patients (transplant recipients, HIV, lymphoma, steroids) — due to impaired T-cell mediated immunity required to control intracellular Listeria"]','A','Listeria is a facultative intracellular pathogen and one of the few organisms causing neonatal meningitis alongside GBS and E. coli. It accounts for ~20% of foodborne deaths despite low incidence. Treatment: ampicillin ± gentamicin synergistically. Cephalosporins have NO activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','medium','flashcard','What is the Quellung reaction and which organism does it identify?','["Quellung (German: ''''swelling'''') reaction: type-specific antibodies bind the polysaccharide capsule of Streptococcus pneumoniae, causing apparent capsular swelling visible under light microscopy — used to serotype pneumococci into >90 capsular serotypes"]','A','The capsule inhibits phagocytosis by blocking C3b deposition. Asplenic patients are particularly vulnerable to encapsulated bacteria (S. pneumoniae, H. influenzae type b, N. meningitidis). PPSV23 and PCV13/PCV20 vaccines target the most virulent serotypes. S. pneumoniae is the commonest cause of CAP and adult bacterial meningitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','hard','flashcard','What is the mechanism by which Clostridium perfringens alpha-toxin causes gas gangrene?','["Alpha-toxin (lecithinase/phospholipase C) hydrolyses phosphatidylcholine in cell membranes, causing massive haemolysis, myonecrosis, and vascular endothelial damage; anaerobic fermentation produces CO2 and H2 gas (visible on X-ray and CT as subcutaneous/intramuscular gas) — the hallmark of clostridial myonecrosis"]','A','C. perfringens is an obligate anaerobe that thrives in devitalised, hypoxic tissue. Additional toxins: theta-toxin (perfringolysin O, pore-forming). Treatment: surgical debridement is the priority + high-dose benzylpenicillin + hyperbaric oxygen (raises tissue pO2 above the tolerance of obligate anaerobes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-positive','hard','flashcard','How does Corynebacterium diphtheriae toxin inhibit protein synthesis?','["Diphtheria toxin (A-B toxin): B fragment binds host cell receptor (HB-EGF precursor); A fragment enters the cytoplasm and ADP-ribosylates diphthamide (a modified histidine) on elongation factor-2 (EF-2), permanently halting ribosomal translocation and killing all eukaryotic cells"]','A','EF-2 translocates the ribosome from A-site to P-site during translation. Inactivating EF-2 halts all protein synthesis. Identical mechanism to Pseudomonas aeruginosa exotoxin A. The toxin gene is encoded by a corynephage (beta-phage). Treatment: antitoxin (binds unbound toxin) + erythromycin/penicillin. Diphtheria is preventable by DTaP/Td vaccine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','easy','flashcard','What distinguishes ETEC from other diarrhoeagenic E. coli serotypes?','["ETEC produces heat-labile toxin (LT: activates adenylate cyclase → ↑cAMP → Cl- hypersecretion) and/or heat-stable toxin (ST: activates guanylate cyclase → ↑cGMP) causing profuse watery diarrhoea without mucosal invasion — the classic cause of traveller''''s diarrhoea"]','A','LT is structurally and mechanistically identical to cholera toxin (CT). ST is small, non-immunogenic, and not neutralised by anti-CT antibodies. Neither causes bloody stool or bacteraemia. Oral rehydration is the mainstay; rifaximin or azithromycin for moderate-to-severe cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','easy','flashcard','What is the hallmark complication of EHEC O157:H7 and what toxin causes it?','["Haemolytic Uraemic Syndrome (HUS): Shiga-like toxin (Stx1/Stx2, verotoxin) binds Gb3 receptor on glomerular endothelial cells, cleaves 28S rRNA halting protein synthesis → endothelial necrosis → microvascular thrombosis → MAHA + thrombocytopenia + acute kidney injury"]','A','Classic HUS triad: MAHA + thrombocytopenia + AKI. Antibiotics are CONTRAINDICATED (increase toxin release and HUS risk). No bacteraemia or colonic invasion. Transmitted via undercooked beef, unpasteurised dairy/juice. Management: supportive fluid therapy; dialysis if required. Most children recover renal function fully.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','easy','flashcard','What is Waterhouse-Friderichsen syndrome?','["Bilateral haemorrhagic necrosis of both adrenal glands causing acute cortisol and aldosterone deficiency, classically complicating Neisseria meningitidis septicaemia with DIC — presents with purpuric (non-blanching) rash, hypotension, and cardiovascular collapse"]','A','DIC-induced haemorrhage destroys the adrenal cortex. Treat immediately with IV hydrocortisone (bypasses the absent adrenal cortisol production) plus IV benzylpenicillin before hospital transfer. Adrenals appear black, swollen, and completely haemorrhagic at autopsy. Also described with Pseudomonas, Pneumococcus, and Gram-negative sepsis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','medium','flashcard','What does EPEC cause and how does it differ mechanistically from ETEC and EHEC?','["EPEC causes infantile diarrhoea via attaching-and-effacing (A/E) lesions — injects Tir via type III secretion system into enterocyte membrane, then uses intimin adhesin to bind Tir, causing actin pedestal formation and microvillus effacement; NO enterotoxin produced and NO bloody diarrhoea"]','A','EPEC requires relatively high inoculum. Does not invade (unlike Shigella) and does not produce Shiga-like toxin (unlike EHEC). Major cause of infantile diarrhoea in developing countries in children <2 years. Co-trimoxazole or azithromycin shortens illness but antibiotic resistance is common.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','medium','flashcard','What virulence factors of Neisseria gonorrhoeae enable immune evasion?','["IgA1 protease cleaves secretory IgA at the mucosal surface, removing the first line of defence; antigenic variation of pili (pilE gene switching against silent pilS loci) and Opa proteins (phase variation) generates infinite antigenic diversity, preventing lasting protective immunity"]','A','N. gonorrhoeae attaches via pili to CD46 on non-ciliated columnar epithelium. It is an obligate human pathogen with no animal reservoir. Neonatal ophthalmia neonatorum is prevented by erythromycin eye drops. WHO has listed gonorrhoea as a priority pathogen due to rising resistance to azithromycin and ceftriaxone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','medium','flashcard','What are the pathological gut lesions in Salmonella typhi infection?','["S. typhi infects M cells overlying Peyer''''s patches in the terminal ileum → macrophage uptake → lymphoid hyperplasia with ''''typhoid nodules'''' (clusters of macrophages/monocytes) → bacteraemia → rose spots on the trunk (week 2, salmon-coloured macules); Peyer''''s patch necrosis and ileal perforation risk in week 3"]','A','Typhoid: stepwise fever, relative bradycardia (Faget sign), splenomegaly, rose spots. Culture blood in week 1-2 (Salmonella bacteraemia); stool/urine in week 2-3. Widal test (anti-O/anti-H antibodies) used in endemic settings — low specificity. Treatment: azithromycin or IV ceftriaxone (fluoroquinolone resistance widespread). Vaccination: Ty21a (oral attenuated) or Vi polysaccharide (IM).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','medium','flashcard','How does Shigella dysentery differ from Salmonella typhi infection clinically and pathologically?','["Shigella invades colonic mucosa (type III SS + intracellular actin motility) causing bloody dysentery with mucus and pus; very low infective inoculum (<100 organisms); NO bacteraemia. Salmonella typhi causes systemic bacteraemia with minimal colitis, rose spots, and NO bloody stool"]','A','Shiga toxin (S. dysenteriae type 1 only) adds HUS risk on top of dysentery. Shigella escapes phagosome using IpaB/IpaC, polymerises actin (similar to Listeria). Treatment: azithromycin or ciprofloxacin. Avoid anti-motility agents and antibiotics in EHEC (but appropriate in Shigella). Key distinction: Shigella = low inoculum, colitis; Salmonella typhi = high inoculum, systemic illness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','medium','flashcard','What are the key virulence factors of Helicobacter pylori?','["Urease converts urea → NH3 + CO2, neutralising gastric acid for survival; CagA (cytotoxin-associated gene A, injected via type IV secretion system) disrupts epithelial cell tight junctions and promotes gastric carcinogenesis; VacA vacuolating cytotoxin damages gastric epithelium and impairs T-cell responses"]','A','H. pylori is a WHO Group 1 carcinogen for gastric adenocarcinoma (intestinal type) and MALT lymphoma. Diagnosis: urea breath test (best non-invasive), stool antigen test, or CLO test on antral biopsy. Eradication: triple therapy (PPI + clarithromycin + amoxicillin × 7 days) or bismuth quadruple therapy. CagA-positive strains confer higher cancer risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','hard','flashcard','What is the molecular mechanism by which LPS triggers Gram-negative septic shock?','["LPS binds LPS-binding protein (LBP) in serum → LPS-LBP complex binds CD14 on macrophages → presented to TLR4/MD-2 heterodimer → dimerisation of TLR4 → MyD88/TIRAP adaptor recruitment → IRAK4/TRAF6 activation → NF-κB nuclear translocation → massive transcription of TNF-alpha, IL-1, IL-6, IL-12, and COX-2"]','A','Lipid A (hydrophobic anchor of LPS) is the toxic moiety recognised by MD-2. TLR4 also signals via TRIF/TRAM (MyD88-independent pathway) inducing type I interferons (IRF3). Polymorphisms in TLR4 (Asp299Gly) confer hyporesponsiveness to LPS, associated with increased susceptibility to Gram-negative sepsis in some populations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Bacterial Infections — Gram-negative','hard','flashcard','What is the significance of pathogenicity islands in bacterial virulence evolution?','["Pathogenicity islands (PAIs) are clusters of virulence genes (toxins, secretion systems, adhesins, iron-acquisition systems) acquired by horizontal gene transfer, often flanked by insertion sequences or tRNA genes, with different G+C content from the host chromosome — they can convert commensal to pathogenic strains"]','A','Examples: EHEC LEE island (intimin + type III SS); Salmonella SPI-1 and SPI-2 (type III SS for invasion and intracellular survival); H. pylori cag PAI (CagA + type IV SS). PAIs are lost and gained rapidly during evolution, explaining why virulence differences exist between closely related strains (e.g., pathogenic vs non-pathogenic E. coli).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','flashcard','What is the Ghon complex in primary tuberculosis?','["Ghon complex = Ghon focus (subpleural caseating granuloma in the lower lobe or mid-zone) + caseating hilar lymph node enlargement on the same side — together representing the primary TB infection with lymphatic spread to the regional draining nodes"]','A','The Ghon focus heals by fibrosis and calcification (Ranke complex on CXR). Viable bacilli remain dormant for decades. In the first weeks, haematogenous dissemination seeds ''''Simon foci'''' in the lung apices — setting the stage for reactivation TB years later.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','flashcard','What is the Ziehl-Neelsen stain and why is it required for mycobacteria?','["Ziehl-Neelsen (acid-fast stain): hot carbol-fuchsin penetrates the high mycolic acid content of the mycobacterial cell wall and is retained despite acid-alcohol decolourisation — acid-fast bacilli (AFB) stain bright red against a blue methylene blue background"]','A','Mycobacteria cannot be reliably Gram-stained (weakly Gram-positive or Gram-variable). Auramine-rhodamine fluorescent stain is more sensitive for screening sputum (brighter signal, lower power scanning). GeneXpert MTB/RIF (NAAT) detects TB AND rifampicin resistance within 2 hours from sputum — now recommended as initial test by WHO.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','easy','flashcard','What is secondary (reactivation) tuberculosis and where does it typically occur?','["Secondary TB arises in a previously sensitised host when dormant M. tuberculosis bacilli reactivate in the lung apex (Simon foci — seeded during primary bacteraemia), where high O2 tension favours mycobacterial growth — causing apical infiltrates, cavitation, haemoptysis, and high infectivity"]','A','Simon foci were seeded during the primary bacteraemia and remained dormant. Reactivation occurs when immunity wanes: HIV, TNF-alpha inhibitors, diabetes, malnutrition, steroids. Distinguishes secondary from primary TB: upper lobe location, cavitation, smear-positive (high bacillary load in cavities), post-infectious pattern on CXR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','flashcard','What are the histological hallmarks of TB and how do Langhans giant cells differ from foreign body giant cells?','["TB: caseating granulomas with central caseous (cheese-like) necrosis surrounded by epithelioid macrophages and Langhans giant cells (nuclei arranged in a horseshoe or peripheral arc at the cell periphery). Foreign body giant cells have nuclei randomly and centrally scattered throughout the cytoplasm"]','A','Caseating granulomas = TB, histoplasmosis, coccidioidomycosis, cryptococcosis, leprosy. Non-caseating granulomas = sarcoidosis (most common), Crohn''''s disease, berylliosis. Langhans giant cells have up to 50 nuclei formed by macrophage fusion driven by IFN-gamma and TNF-alpha.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','flashcard','How does the tuberculin PPD skin test work and what are its limitations?','["PPD injected intradermally elicits type IV delayed-type hypersensitivity (DTH) mediated by sensitised memory CD4+ T-cells releasing IFN-gamma and attracting macrophages — induration ≥10mm at 48-72 hours indicates prior sensitisation (infection or BCG vaccination)"]','A','False negatives: severe immunosuppression (HIV, steroids, lymphoma), overwhelming active TB, malnutrition, sarcoidosis. False positives: BCG vaccination (cannot distinguish from infection), NTM exposure. IGRA (QuantiFERON-TB Gold or T-SPOT.TB) measures IFN-gamma response to ESAT-6/CFP-10 — more specific, not affected by BCG, preferred in BCG-vaccinated populations.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','flashcard','What are the distinguishing features of tuberculoid vs lepromatous leprosy?','["Tuberculoid: strong TH1 CMI, few bacilli (paucibacillary), dry anaesthetic hypopigmented skin patches, asymmetric large peripheral nerve enlargement (nerve thickening palpable), AFB smear negative, Lepromin test positive. Lepromatous: weak CMI (TH2), many bacilli (multibacillary), diffuse symmetric skin thickening, leonine facies, Virchow cells (macrophages teeming with bacilli), Lepromin negative"]','A','Virchow cells (globi) are lipid-laden macrophages packed with M. leprae in lepromatous leprosy. M. leprae cannot be cultured in vitro. Preferentially infects Schwann cells and cooler skin (ears, nose, elbows). WHO MDT: dapsone + rifampicin for paucibacillary; + clofazimine for multibacillary. Nerve damage causes glove-and-stocking sensory loss and consequent traumatic injury.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','medium','flashcard','What is miliary tuberculosis?','["Miliary TB: haematogenous dissemination of M. tuberculosis producing countless 1-2mm caseating granulomas (resembling millet seeds) throughout the lungs, liver, spleen, bone marrow, adrenals, and meninges — occurring when a caseous lymph node or pulmonary focus erodes into a blood vessel"]','A','CXR/CT: bilateral diffuse micronodular (miliary) pattern. More common in immunocompromised patients and young children. Miliary TB in the meninges causes tuberculous meningitis — a medical emergency with high mortality. Morning serum ACE is elevated in 50% (similar to sarcoidosis). Full 4-drug TB treatment required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','flashcard','What is the role of IFN-gamma in the immune response to Mycobacterium tuberculosis?','["IFN-gamma (from TH1 cells and NK cells, triggered by IL-12 from macrophages) activates macrophages to produce reactive oxygen and nitrogen species (ROI/RNI), mobilise antimicrobial peptides (defensins), stimulate autophagy (sequestering mycobacteria in autophagosomes), and upregulate MHC class II for better antigen presentation"]','A','Defects in the IL-12/IFN-gamma axis (Mendelian susceptibility to mycobacterial disease — MSMD) cause severe disseminated infections even with low-virulence mycobacteria. Anti-TNF-alpha therapy (infliximab, adalimumab) disrupts granuloma integrity, reactivating latent TB — mandatory TB screening before commencing anti-TNF biologics.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','flashcard','Why do TB granulomas undergo caseating necrosis and what is its clinical significance?','["Caseous necrosis results from macrophage death during DTH reactions — lysosomal enzymes and reactive oxygen species kill bacilli and surrounding macrophages; the resulting hypoxic, acidic caseum is initially bacteriostatic but if liquefied (driven by matrix metalloproteinases) provides an ideal nutrient-rich culture medium enabling exponential bacterial replication and airway spread"]','A','Liquefied caseum in secondary TB forms thick-walled cavities containing up to 10^9 bacilli/mL — making the patient highly infectious (sputum smear-positive AFB). Air-filled cavities visible on CXR in upper lobes. Post-TB cavities can be colonised by Aspergillus (aspergilloma). ''''Caseous'''' from Latin caseus (cheese) — the material resembles soft crumbly white cheese.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','easy','flashcard','What are the characteristic histological findings in HSV infection?','["Intranuclear Cowdry type A inclusions (eosinophilic, ground-glass, with clear chromatin halo pushed to the nuclear membrane) in infected cells, plus multinucleated giant cells (syncytia) formed by HSV glycoprotein-mediated cell membrane fusion"]','A','Cowdry A inclusions are also seen in CMV and VZV. Tzanck smear from a fresh vesicle base demonstrates multinucleated giant cells rapidly at the bedside — quick but non-specific for herpesviruses. HSV-1 latency in trigeminal ganglia (oral HSV); HSV-2 in sacral ganglia (genital HSV). Neonatal HSV from birth canal can cause disseminated/CNS disease with high mortality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','easy','flashcard','What are CMV owl-eye inclusions and what congenital complications does CMV cause?','["CMV causes greatly enlarged cells with large intranuclear inclusions surrounded by a clear halo (''''owl-eye'''' inclusions) plus smaller cytoplasmic inclusions; congenital CMV causes periventricular calcifications, sensorineural hearing loss, microcephaly, hepatosplenomegaly, petechiae (''''blueberry muffin'''' baby), and chorioretinitis"]','A','CMV is the commonest congenital viral infection (~1% of births). Periventricular calcifications (clusters around lateral ventricles) distinguish CMV from congenital toxoplasmosis (diffuse cortical/basal ganglia calcifications). CMV is the leading non-genetic cause of sensorineural hearing loss. SNHL can develop months after birth — emphasising need for universal newborn hearing screening.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','easy','flashcard','What is the Paul-Bunnell test and what heterophile antibodies does EBV infection produce?','["The Paul-Bunnell test detects heterophile IgM antibodies (produced non-specifically during EBV mononucleosis) that agglutinate sheep or horse red blood cells; the rapid Monospot latex test exploits this principle — a positive result with clinical triad (fever, pharyngitis, lymphadenopathy) is diagnostic of EBV infectious mononucleosis"]','A','Heterophile antibodies appear in weeks 1-2, persist ~6 weeks, and are absent in EBV-negative (CMV) mononucleosis. False negatives in children <4 years. EBV-infected B-cells can resemble Reed-Sternberg cells histologically in lymph nodes — avoid over-diagnosing Hodgkin lymphoma. EBV-specific VCA-IgM confirms acute infection when Monospot is negative.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','medium','flashcard','What are Downey type II cells and in what condition are they found?','["Downey type II cells are reactive (atypical) lymphocytes — large CD8+ cytotoxic T-cells with abundant pale blue cytoplasm that ''''hugs'''' adjacent RBCs, representing the immune response to EBV-infected B-cells; they are prominent in infectious mononucleosis (EBV) on peripheral blood smear"]','A','These are CD8+ T-cells (the immune response), NOT the infected B-cells. >10% atypical lymphocytes on blood film + positive Monospot + pharyngitis + cervical LAD + splenomegaly = classic EBV mono. Avoid ampicillin/amoxicillin (causes morbilliform rash from immune complex deposition). Avoid contact sports for 4 weeks (risk of splenic rupture). Complications: airway obstruction, haemolytic anaemia, encephalitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','medium','flashcard','How do HPV E6 and E7 oncoproteins cause cervical carcinoma?','["E6 binds p53 and promotes its ubiquitin-proteasomal degradation (removes DNA damage checkpoint and apoptosis); E7 binds and inactivates pRb (releases E2F transcription factors, removing the G1→S cell cycle brake) — together driving uncontrolled proliferation and accumulation of genomic mutations in cervical squamous epithelium"]','A','High-risk HPV types 16 and 18 account for ~70% of cervical cancers. E6/E7 are expressed from INTEGRATED HPV DNA (not episomal) — integration disrupts E2, the viral repressor of E6/E7. HPV16 → squamous cell carcinoma; HPV18 → adenocarcinoma. Gardasil 9 protects against HPV 6/11/16/18/31/33/45/52/58. Cervical screening (smear/colposcopy) detects CIN before invasive carcinoma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','medium','flashcard','What are the serological markers of hepatitis B and what does each indicate?','["HBsAg = active infection; HBeAg = active viral replication and high infectivity; Anti-HBs = protective immunity (post-vaccination or cleared infection); Anti-HBc IgM = acute infection; Anti-HBc IgG = past exposure (including window period); HBV DNA = quantitative viral load for treatment monitoring"]','A','Window period: HBsAg cleared, anti-HBs not yet detectable — ONLY anti-HBc IgM positive. Ground-glass hepatocytes (HBsAg-laden smooth ER) on biopsy = chronic HBV. Dane particle = complete infectious virion (42nm). Perinatal transmission: 90% chronicity risk (vs 5% adult). Tenofovir or entecavir (anti-reverse-transcriptase) for chronic HBV with active replication or fibrosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','medium','flashcard','What is the significance of ground-glass hepatocytes in liver biopsy?','["Ground-glass hepatocytes contain abundant smooth endoplasmic reticulum packed with HBsAg, giving a finely granular pale pink homogeneous cytoplasm on H&E staining — pathognomonic of chronic hepatitis B infection"]','A','Confirmed by orcein stain or Victoria blue stain (HBsAg stains dark brown). Hepatocyte damage in HBV is immune-mediated (CD8+ cytotoxic T-cells attacking HBsAg-presenting hepatocytes), NOT directly cytopathic. The ground-glass cells themselves are NOT necrotic. Fibrosis progression depends on viral load, HBeAg status, HDV co-infection, and alcohol co-exposure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','hard','flashcard','How does EBV evade immune elimination in latently infected B-cells?','["EBV produces viral IL-10 (vIL-10/BCRF1) that suppresses TH1 responses and dendritic cell function; LMP1 mimics constitutively active CD40, preventing B-cell apoptosis; EBNA2 drives B-cell proliferation; LMP2A mimics BCR signalling maintaining B-cell survival; BHRF1 (Bcl-2 homologue) blocks intrinsic apoptosis"]','A','In immunocompromised patients (post-transplant, AIDS), failure of CD8+ surveillance allows EBV-driven B-cell proliferation leading to post-transplant lymphoproliferative disorder (PTLD), CNS lymphoma (AIDS), or Burkitt''''s lymphoma (c-myc translocation). EBV also downregulates MHC class I (TAP1 inhibition) to evade CD8+ T-cells.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','hard','flashcard','What is the structure of the hepatitis B Dane particle and how does HBV replicate via reverse transcription?','["Dane particle (42nm complete HBV virion): outer lipid envelope (HBsAg) + icosahedral nucleocapsid (HBcAg) + partially double-stranded relaxed circular DNA (rcDNA) + viral DNA polymerase (with reverse transcriptase domain). Replication: rcDNA → cccDNA (nuclear) → pregenomic RNA → reverse-transcribed back to DNA by viral RT — HBV is a pararetrovirus"]','A','cccDNA (covalently closed circular DNA) is the episomal transcriptional template that persists in nuclei indefinitely — explaining why HBV cannot be cured by current antivirals (which block RT but not cccDNA transcription). Tenofovir and entecavir are analogues that block the RT step. HDV (delta virus) is a defective RNA virus requiring HBsAg for its envelope — always co-infects or superinfects HBV.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','easy','flashcard','What are Koplik spots and what do they signify?','["Koplik spots are pathognomonic of measles — small (1-2mm) bluish-white spots with an erythematous halo on the buccal mucosa opposite the lower molars, appearing 1-2 days before the maculopapular rash during the prodromal stage"]','A','Measles rash begins behind the ears and hairline, then spreads head-to-toe (centrifugal). Complications: otitis media (commonest), pneumonia (giant cell Hecht''''s pneumonia), encephalitis (1:1000), SSPE (rare, 7-10 years later). Measles causes profound T-cell lymphopenia and ''''immune amnesia'''' lasting months, increasing susceptibility to secondary infections.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','easy','flashcard','At what CD4 counts do AIDS-defining opportunistic infections appear?','["CD4 <500/µL: oral candidiasis, hairy leukoplakia; CD4 <200/µL: PCP (Pneumocystis jirovecii), Toxoplasma encephalitis, progressive multifocal leukoencephalopathy; CD4 <100/µL: Cryptococcal meningitis, CNS Toxoplasma; CD4 <50/µL: CMV retinitis, disseminated MAC"]','A','Memory: 500-200-100-50. PCP prophylaxis (TMP-SMX) starts at CD4 <200; MAC prophylaxis (azithromycin weekly) at CD4 <50. All thresholds guide specific prophylaxis and monitoring. Current WHO guidance: start ART at any CD4 count (START trial: treatment at CD4 >500 reduces AIDS and non-AIDS events).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','easy','flashcard','What is the difference between antigenic drift and shift in influenza A?','["Drift: gradual point mutations in HA or NA genes → minor antigenic changes → seasonal flu epidemics requiring annual vaccine updates. Shift: sudden reassortment of entire RNA segments between two influenza A strains (e.g., human + avian strains reassort in a pig ''''mixing vessel'''') → novel HA/NA subtype → pandemic potential because no population immunity exists"]','A','Only influenza A undergoes shift (has animal reservoirs — birds and pigs). Influenza B only drifts (human-only reservoir). Pandemics: 1918 H1N1 (''''Spanish flu'''', 50 million deaths), 1957 H2N2, 1968 H3N2 (''''Hong Kong''''), 2009 H1N1pdm. HA (18 types) binds sialic acid; NA (11 types) cleaves sialic acid enabling virion release.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','medium','flashcard','What laboratory tests diagnose dengue fever and at what stage of illness?','["Days 1-5 (viraemia): NS1 antigen ELISA/RDT (>85% sensitivity) and PCR (most sensitive). From day 3-5: dengue IgM antibody appears (peaks week 2, persists months). Full blood count: falling platelet count and rising haematocrit (haemoconcentration) signal DHF development"]','A','NS1 (non-structural protein 1) is secreted by infected cells into blood — detectable before IgM. IgG rises during secondary infection and persists lifelong. Platelet <100,000/µL + haematocrit rise >20% = key DHF diagnostic criteria. Tourniquet test ≥20 petechiae/in² reflects capillary fragility in DHF/dengue shock syndrome (DSS).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','medium','flashcard','What is the pathogenesis of dengue haemorrhagic fever (DHF)?','["DHF occurs during secondary infection with a different dengue serotype — pre-existing non-neutralising antibodies enhance viral uptake into monocytes/macrophages (antibody-dependent enhancement, ADE) → uncontrolled viral replication + massive cytokine release → increased vascular permeability → plasma leakage, haemoconcentration, thrombocytopenia, haemorrhage"]','A','Four dengue serotypes (DENV 1-4). First infection = dengue fever; second infection with different serotype + ADE = DHF/DSS risk. Plasma leakage (not primarily DIC) is the hallmark. IV fluid management is critical — both under-resuscitation (hypovolaemic shock) and over-resuscitation (pulmonary oedema) are dangerous. No specific antiviral therapy currently available.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','medium','flashcard','Why does RSV bronchiolitis predominantly affect infants under 6 months?','["Infants <6 months have narrow bronchiolar lumen (small calibre = high resistance to airflow), immature innate/adaptive immunity, waning maternal IgG, and no prior RSV exposure — RSV infects bronchiolar epithelium causing oedema, mucous plugging, and sloughing of ciliated cells → air trapping, hyperinflation, atelectasis, and hypoxia"]','A','RSV is the commonest cause of bronchiolitis and infant hospitalisation worldwide. Premature infants, CHD, and BPD confer highest risk. Palivizumab (anti-RSV monoclonal antibody) prophylaxis for high-risk groups. Nirsevimab (single-dose monoclonal) approved for all infants. Diagnosis: nasopharyngeal swab RSV antigen or PCR. Treatment: supportive O2 and hydration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','medium','flashcard','What is the HIV life cycle and which antiretroviral drug class targets each step?','["HIV gp120 binds CD4 + CCR5/CXCR4 co-receptor (entry inhibitors: enfuvirtide, maraviroc) → reverse transcriptase converts RNA to dsDNA (NRTIs/NNRTIs) → integrase inserts proviral DNA into host chromosome (integrase inhibitors: dolutegravir, raltegravir) → protease cleaves Gag-Pol polyprotein into mature proteins (protease inhibitors: darunavir)"]','A','CCR5 (R5 strains, macrophage-tropic) vs CXCR4 (X4 strains, T-cell-tropic). CCR5-Δ32 homozygotes are naturally resistant to R5 HIV. Current preferred first-line ART: 2 NRTIs + integrase inhibitor (dolutegravir + TDF/FTC per WHO 2019). ART is lifeline treatment: suppresses viral load to undetectable, immune reconstitution, and prevents onward transmission (U=U: undetectable = untransmittable).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','hard','flashcard','What is Subacute Sclerosing Panencephalitis (SSPE) and how does it relate to measles virus?','["SSPE is a fatal progressive encephalitis occurring 7-10 years after measles infection, caused by a replication-defective mutant measles virus with defective M protein that cannot assemble complete virions — the virus persists in CNS neurons causing progressive neurodegeneration: personality change → myoclonic jerks → seizures → dementia → akinetic mutism → death"]','A','EEG: pathognomonic periodic Radermecker complexes. CSF: markedly elevated anti-measles IgG. Brain histology: Cowdry A inclusions in neurons and oligodendrocytes, perivascular lymphocytes, demyelination. Measles vaccination has reduced SSPE incidence 10-fold. No proven treatment — ribavirin + isoprinosine may slow progression. The virus cannot be cleared because it does not produce infectious particles to trigger a new immune response.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','hard','flashcard','What is the mechanism of influenza haemagglutinin (HA) receptor binding and how do neuraminidase inhibitors work?','["Influenza HA (homotrimer) binds sialic acid linked to galactose on host cell surface (alpha-2,6 linkages in human upper respiratory tract; alpha-2,3 in avian and lower human respiratory tract) mediating viral entry. Neuraminidase (NA) inhibitors (oseltamivir, zanamivir) bind the NA active site, blocking cleavage of sialic acid from cell surface — trapping newly budded virions and preventing spread"]','A','Human URT has alpha-2,6 sialic acid linkages; avian/lower human RT has alpha-2,3. This difference restricts bird flu (H5N1) mainly to the deep lung, limiting human-to-human transmission. Oseltamivir resistance: H275Y mutation in NA. Baloxavir marboxil is a newer agent targeting cap-dependent endonuclease (PA subunit of RNA-dependent RNA polymerase) — single dose, active against oseltamivir-resistant strains.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','easy','flashcard','What is the germ tube test and which organism does a positive result identify?','["The germ tube test identifies Candida albicans: incubated in human serum at 37°C for 2-3 hours, C. albicans produces germ tubes — short hyphal outgrowths with NO constriction at the origin — within 2-3 hours; a positive test is a rapid presumptive identification of C. albicans"]','A','Germ tube = true hypha directly from yeast cell (no constriction distinguishes from pseudohypha). ~95% sensitive for C. albicans (C. dubliniensis also positive). Other Candida spp. are germ-tube negative. Chromogenic agar (CHROM agar Candida) identifies multiple species by colony colour. API Candida or MALDI-TOF mass spectrometry for definitive identification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','easy','flashcard','How is Cryptococcus neoformans identified on India ink preparation?','["India ink creates a dark background against which the polysaccharide capsule of C. neoformans appears as a large clear halo surrounding the narrow-necked budding yeast cell — the large capsule physically excludes the India ink carbon particles"]','A','India ink is positive in ~50% of HIV-associated cryptococcal meningitis. Cryptococcal capsular antigen (CrAg) lateral flow assay is >95% sensitive in serum and CSF — now the preferred rapid diagnostic test. Mucicarmine stains the polysaccharide capsule red. C. neoformans grows on Sabouraud agar at 37°C; melanin pigment turns colonies brown on birdseed agar.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','easy','flashcard','What are the characteristic features of Aspergillus fumigatus in tissue sections?','["Aspergillus: septate hyphae of uniform width (3-6 µm) branching at 45-degree ACUTE angles, angioinvasive — hyphae penetrate vessel walls causing haemorrhagic infarction and the ''''halo sign'''' (ground-glass opacity around a nodule) on CT in invasive pulmonary aspergillosis"]','A','Mnemonic: Aspergillus = Acute angles (45°), septate. Mucor/Rhizopus = right angles (90°), no septa (pauciseptate). GMS or PAS stains are best for fungi in tissue. Serum galactomannan antigen (Aspergillus cell wall component) and beta-D-glucan help diagnose invasive aspergillosis non-invasively. Voriconazole is first-line treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','flashcard','What is an aspergilloma and what pre-existing condition is required?','["An aspergilloma (fungus ball) is a tangled mass of Aspergillus hyphae + mucus + cellular debris that colonises a pre-existing pulmonary cavity (from prior TB, sarcoidosis, emphysematous bullae, or bronchiectasis) — the fungus grows saprophytically WITHOUT tissue invasion"]','A','CT/CXR: round mass within a cavity with surrounding airspace (''''Monod sign'''' or ''''air crescent sign'''') that moves with gravity on positional CT. Can cause massive haemoptysis via erosion of bronchial vessels. Anti-Aspergillus IgG precipitins strongly positive. Serum galactomannan may be negative (no angioinvasion). Treatment: voriconazole ± surgical resection for haemoptysis or symptomatic disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','flashcard','Why is Cryptococcus neoformans especially dangerous in HIV patients with CD4 <100?','["C. neoformans polysaccharide capsule inhibits phagocytosis and complement opsonisation; melanin (laccase enzyme product) scavenges reactive oxygen species counteracting macrophage killing; mannitol (mannitol dehydrogenase product) causes osmotic brain oedema; grows well at 37°C — and without CD4+ T-cell-mediated immunity, it cannot be contained"]','A','C. neoformans found in pigeon droppings and soil. CNS: ''''soap bubble'''' gelatinous pseudocysts in basal ganglia (lack inflammatory infiltrate due to absent CMI). Elevated ICP (>25 cmH2O) is the leading cause of early mortality — serial therapeutic LPs lower ICP (target <20 cmH2O). Treatment: liposomal amphotericin B + 5-flucytosine × 2 weeks → fluconazole consolidation/maintenance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','medium','flashcard','What is Histoplasma capsulatum and how does it appear in tissue?','["Histoplasma capsulatum: dimorphic fungus (mold at 25°C; small oval yeast at 37°C in tissue); endemic to Ohio/Mississippi River Valley; appears in tissue as 2-4 µm oval yeast cells packed within macrophage cytoplasm with an artefactual ''''halo'''' (acapsulate despite its name — the halo is cytoplasmic retraction on H&E)"]','A','Infects via inhalation of microconidia from bat and bird droppings (caves, old buildings, chicken coops). In immunocompetent: self-limiting pulmonary illness (often asymptomatic or flu-like). Disseminated (HIV): fever, hepatosplenomegaly, pancytopenia, adrenal involvement. Diagnosis: urine/serum Histoplasma antigen EIA (best), culture. Treatment: itraconazole (mild-moderate), liposomal amphotericin B (severe).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','flashcard','What distinguishes Candida pseudohyphae from true hyphae morphologically and in terms of virulence?','["Pseudohyphae: chains of elongated blastoconidia (budding yeast cells) that remain attached end-to-end WITH visible constrictions at junctions (pinched waist, ''''bamboo-like''''). True hyphae: parallel-walled with NO constrictions at septa, formed from germ tubes. Hyphal/pseudohyphal morphology correlates with increased tissue invasiveness, biofilm formation, and escape from phagocytosis"]','A','The yeast-hypha switch in C. albicans is triggered by temperature >37°C, serum, alkaline pH, and CO2. Key virulence genes activated in hyphal form: ALS3 (adhesin), SAP5/6 (secreted proteases), ECE1/candidalysin (pore-forming toxin). Biofilm on catheters is 100-1000x more resistant to antifungals — requires catheter removal. C. glabrata (now Nakaseomyces glabrata) forms only yeast, yet is an increasingly important pathogen due to azole resistance.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','flashcard','What distinguishes mucormycosis from aspergillosis histologically and which patients are at risk?','["Mucormycosis: broad (10-20 µm) pauciseptate/aseptate hyphae branching at 90-degree RIGHT angles; angioinvasion causes haemorrhagic infarction more rapidly and extensively than Aspergillus. Highest risk: DKA (excess free iron fuels fungal growth + high glucose), neutropenia, deferoxamine therapy (chelated iron = siderophore for Mucor), severe burns"]','A','Rhinocerebral mucormycosis: nasal congestion/discharge → black eschar on nasal/palatal mucosa → orbital cellulitis → cavernous sinus thrombosis → CNS invasion. Mortality >50% even with treatment. Treatment: immediate surgical debridement + liposomal amphotericin B. Voriconazole (Aspergillus drug) has NO activity against Mucor — a critical distinction. Isavuconazole has activity against both.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','flashcard','What are the endemic dimorphic fungi and how do they differ from opportunistic fungi?','["Endemic dimorphic fungi (infect immunocompetent people in specific geographic areas): Histoplasma capsulatum (Ohio/Mississippi valley), Coccidioides immitis/posadasii (SW USA/Sonoran Desert), Blastomyces dermatitidis (Great Lakes/SE USA). All are mold at 25°C and yeast (or spherule) at 37°C in tissue. Opportunistic fungi (Candida, Aspergillus, Cryptococcus, Mucor) primarily cause disease in immunocompromised hosts"]','A','Coccidioides is unique — forms spherules (not yeast) in tissue, each containing endospores. Coccidioidomycosis (''''Valley Fever''''): primary pulmonary → dissemination to meninges (commonest cause of fungal meningitis in SW USA; dark-skinned populations have higher dissemination risk). Blastomyces: broad-based budding yeast (8-15 µm), ''''pilot wheel'''' on wet prep. All three cause CXR abnormalities mimicking TB.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','easy','flashcard','What distinguishes Plasmodium falciparum from all other malaria species?','["P. falciparum infects RBCs of ALL ages (not restricted to young/old), achieves the highest parasitaemia, lacks Schüffner dots, has NO hypnozoites (no relapse), produces banana-shaped gametocytes, and uniquely causes severe/cerebral malaria via PfEMP-1-mediated cytoadherence of infected RBCs to cerebral endothelium (ICAM-1, CD36)"]','A','Only P. falciparum causes: cerebral malaria, ARDS, hypoglycaemia (parasite metabolism + quinine stimulates insulin), blackwater fever (massive intravascular haemolysis + haemoglobinuria → AKI). Thick/thin blood smear shows multiple ring forms per cell. Treatment: artemisinin-based combination therapy (ACT); IV artesunate for severe disease (superior to quinine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','easy','flashcard','What are hypnozoites and which Plasmodium species produce them?','["Hypnozoites are dormant intrahepatic liver-stage parasites of P. vivax and P. ovale that persist for months to years and cause relapsing malaria (new blood-stage infection) without re-exposure to mosquitoes — P. falciparum and P. malariae do NOT form hypnozoites"]','A','Primaquine (check G6PD first — causes haemolytic anaemia in G6PD-deficient patients) is the ONLY drug that eliminates hypnozoites and prevents relapse. Tafenoquine is a single-dose alternative. P. vivax infects reticulocytes (young RBCs); chloroquine-resistant in Papua New Guinea and Indonesia. P. ovale is rare; only in West Africa and some Pacific islands.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','easy','flashcard','What nephrotic syndrome complication is associated with Plasmodium malariae?','["P. malariae causes quartan malarial nephropathy — immune complex deposition (malarial antigen + IgG/IgM + complement) in glomerular capillaries → membranoproliferative GN → nephrotic syndrome (proteinuria, hypoalbuminaemia, oedema), particularly in chronically infected African children"]','A','P. malariae: quartan fever (72-hour cycle), infects old/senescent RBCs. Persists as sub-microscopic parasitaemia for decades (no hypnozoite — different persistence mechanism). Still chloroquine-sensitive. Renal damage may be irreversible even after parasite eradication. GN is immune-complex mediated (Type III hypersensitivity), not direct parasite invasion of kidney.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','flashcard','What is Symmers pipe-stem fibrosis and which parasite causes it?','["Symmers clay pipe-stem fibrosis: dense periportal fibrosis (around portal tracts) caused by the chronic TH2 eosinophilic granulomatous response to trapped Schistosoma mansoni or S. japonicum eggs — produces portal hypertension WITHOUT hepatocellular damage (hepatocytes remain intact, no cirrhosis)"]','A','Periportal fibrosis produces the characteristic ''''pipe-stem'''' appearance on cut liver surface. Portal hypertension → oesophageal varices + massive splenomegaly + ascites. Unlike alcoholic cirrhosis, liver synthetic function is preserved (low hepatic encephalopathy risk). S. haematobium → bladder granulomas → squamous cell carcinoma of the bladder (SCC associated with bilharzia in Egypt/Africa).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','flashcard','What is the congenital toxoplasmosis triad?','["Classic congenital toxoplasmosis triad: (1) chorioretinitis (commonest, >90%, can be bilateral), (2) hydrocephalus (aqueductal stenosis from periventricular inflammation), (3) diffuse intracranial calcifications throughout brain parenchyma — contrast with CMV (periventricular calcifications only)"]','A','T. gondii definitive host = cat. Transplacental transmission: frequent but less severe in third trimester; rare but more severe in first trimester. Maternal primary infection risk: avoid cat litter, undercooked meat, and contaminated garden soil. Treatment of congenital toxo: pyrimethamine + sulfadiazine + folinic acid for 12 months. SNHL, intellectual disability, and visual impairment are long-term sequelae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','flashcard','What is the mechanism of cerebral malaria in P. falciparum infection?','["P. falciparum-infected RBCs express PfEMP-1 on knob-like protrusions, mediating cytoadherence to endothelial ICAM-1 and CD36 in cerebral microvasculature → microvascular sequestration → obstruction + local inflammation + ischaemia/hypoxia → blood-brain barrier breakdown → cerebral oedema → coma"]','A','Rosetting (infected RBCs binding uninfected RBCs via PfEMP-1/complement receptor 1) and platelet-mediated clumping worsen microvascular obstruction. Cerebral malaria has 15-20% mortality even with optimal treatment; 25% survivors have neurological sequelae. IV artesunate is the treatment of choice (superior to quinine in AQUAMAT and SEAQUAMAT trials).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','medium','flashcard','What is the mechanism of immune evasion of adult Schistosoma mansoni in mesenteric veins?','["Adult S. mansoni camouflage their tegument by acquiring host surface antigens (ABO blood group antigens, MHC class I molecules, complement regulatory proteins CD55/CD59) — making them appear as ''''self'''' to the host immune system, enabling survival in mesenteric veins for 20-30 years despite an active immune response against their eggs"]','A','Paradox: strong eosinophilic (TH2/IgE) immunity against cercariae and eggs (causing immunopathology — granulomas, fibrosis) but adults are immunologically invisible. Concomitant immunity develops against reinfection with new cercariae while adults persist. Praziquantel causes tegument disruption, exposing antigens and enabling immune-mediated killing.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','flashcard','How does Entamoeba histolytica cause flask-shaped colonic ulcers?','["E. histolytica trophozoites produce cysteine proteases that degrade the mucin layer and ECM; amoebapores (pore-forming peptides) insert into epithelial cell membranes causing lysis; the ulcer is narrow at the surface epithelium but expands laterally in the more resistant submucosa — producing the characteristic flask (ampullary) shape visible on biopsy"]','A','Pathognomonic finding: RBCs within trophozoite cytoplasm (erythrophagocytosis). Minimal inflammatory infiltrate (E. histolytica lyses neutrophils using amoebapores). Amoebic dysentery: profuse bloody mucoid diarrhoea. Liver abscess (right lobe, single): ''''anchovy paste'''' or chocolate-coloured sterile fluid (lysed hepatocytes). Treatment: metronidazole (invasive disease) then diloxanide furoate (luminal cyst elimination).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','flashcard','What are Schüffner dots and which Plasmodium species show them on blood smear?','["Schüffner dots (eosinophilic stippling of the infected enlarged RBC cytoplasm on Giemsa stain) are parasite-induced modifications of the RBC membrane — present in P. vivax (James dots) and P. ovale (Schüffner dots); ABSENT in P. falciparum (no RBC enlargement, no dots) and P. malariae (no enlargement, band trophozoites but no dots)"]','A','RBC morphology on thin smear aids species identification: enlarged RBC + Schüffner dots = P. vivax or P. ovale; normal-sized RBC + multiple ring forms + banana gametocytes = P. falciparum; normal/small RBC + band-form trophozoites = P. malariae. WHO recommends RDT (rapid antigen detection) alongside microscopy for point-of-care diagnosis in endemic settings.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Parasitic Infections','hard','flashcard','What is the Toxoplasma gondii mechanism for surviving within macrophage phagolysosomes?','["T. gondii tachyzoites resist phagolysosomal killing by: (1) secreting ROP18 kinase (via rhoptries) that phosphorylates and inactivates IRGs (immunity-related GTPases) preventing reactive oxygen burst; (2) the parasitophorous vacuole membrane (PVM) does not fuse with lysosomes; (3) T. gondii inhibits IFN-gamma signalling in the host cell; (4) blocks macrophage apoptosis to ensure host cell survival"]','A','Tachyzoites (rapidly replicating, acute infection) convert to bradyzoite-containing tissue cysts (brain, eye, skeletal muscle) that persist lifelong — usually controlled by CMI. Immunosuppression (low CD4) triggers tachyzoite reactivation → encephalitis. Type II strains (Me49 genotype) cause most human disease including AIDS reactivation. Pyrimethamine inhibits T. gondii DHFR; sulfadiazine inhibits DHPS.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','easy','flashcard','What causes lymphatic filariasis and what are its clinical consequences?','["Wuchereria bancrofti (commonest; Culex mosquito vector) adult worms obstruct lymphatic vessels → lymphoedema of lower limbs/genitalia; chronic infection → elephantiasis (massive skin thickening and deformity) and hydrocele; Brugia malayi/timori cause similar disease in Asia"]','A','Microfilariae circulate with nocturnal periodicity (peak at midnight, coinciding with Culex biting). Diagnosis: midnight thick blood smear, or filarial antigen card test (detects W. bancrofti antigen). Treatment: DEC + albendazole (annual mass drug administration for elimination). Tropical pulmonary eosinophilia = hypersensitivity to microfilariae (cough, wheeze, high IgE).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','easy','flashcard','What is Chagas disease and what are its chronic manifestations?','["Chagas disease (Trypanosoma cruzi; reduviid/kissing bug vector Triatoma): chronic infection destroys autonomic ganglia (myenteric plexus of Auerbach) → dilated cardiomyopathy, conduction defects (RBBB, left anterior fascicular block, bradyarrhythmias, sudden death), mega-oesophagus (progressive dysphagia), megacolon (severe constipation)"]','A','Romaña sign = painless unilateral periorbital oedema (entry via conjunctiva from infected bug faeces). Amastigotes cluster in cardiac myocytes (pseudocysts). ~8 million infected in Latin America; a major cause of heart failure in South America. Treatment: benznidazole or nifurtimox (effective in acute/congenital disease; partial benefit in chronic indeterminate phase; limited in late cardiac/GI Chagas).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','easy','flashcard','What vector transmits African sleeping sickness and what are the two disease stages?','["Trypanosoma brucei is transmitted by the tsetse fly (Glossina). Stage 1 (haemolymphatic): fever, cervical lymphadenopathy (Winterbottom''''s sign = posterior cervical LAD in T.b. gambiense), splenomegaly, chancre at bite site, circulating trypanosomes. Stage 2 (meningoencephalitic): personality change, sleep-wake cycle reversal, tremor, seizures, coma, death if untreated"]','A','T.b. gambiense (West Africa): chronic, years, human reservoir (anthroponotic). T.b. rhodesiense (East Africa): acute, virulent, zoonotic (cattle/game reservoir). Diagnosis: blood/CSF microscopy for trypanosomes; CSF pleocytosis >5 WBC/µL defines Stage 2. Treatment: Stage 1 pentamidine (gambiense) or suramin (rhodesiense); Stage 2 eflornithine + nifurtimox (gambiense) or melarsoprol (both, but toxic — 5% encephalopathic deaths).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','flashcard','What are the three clinical forms of Leishmaniasis and their causative species?','["Cutaneous (oriental sore): L. major, L. tropica, L. mexicana — painless self-healing ulcer with raised indurated border. Mucocutaneous (espundia): L. braziliensis — destructive lesions of nasal septum, palate, and pharynx (''''tapir nose''''). Visceral (kala-azar): L. donovani — fever, progressive weight loss, massive hepatosplenomegaly, pancytopenia, hyperpigmentation (''''black fever''''), death if untreated"]','A','Vector: Phlebotomus sandfly (Old World) or Lutzomyia (New World). Amastigotes infect macrophages throughout the RES in visceral leishmaniasis. Diagnosis: splenic aspirate (gold standard, most sensitive), bone marrow biopsy, or rK39 RDT serology. Treatment: liposomal amphotericin B (first-line for visceral) or miltefosine (oral). Post-kala-azar dermal leishmaniasis (PKDL) is an important ongoing transmission reservoir.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','flashcard','What is Loa loa and how does it present clinically?','["Loa loa (African eyeworm) transmitted by Chrysops deer fly; adult worms migrate subcutaneously causing Calabar swellings (transient migratory angioedema, typically forearms and wrists, lasting hours to days) and visible subconjunctival migration across the eye (seen by the patient, causing pain, irritation, and visible worm under the conjunctiva)"]','A','Microfilariae show diurnal periodicity (peak noon blood count, matching Chrysops daytime feeding). Treatment: diethylcarbamazine (DEC) effective against microfilariae and adult worms. CAUTION: ivermectin is CONTRAINDICATED with high microfilarial loads (>8000 mf/mL) — risk of Mazzotti-like severe encephalopathy and death. Endemic in Central and West African rainforest. ''''Loiasis'''' diagnosis: noon blood smear for microfilariae.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','flashcard','What is the immune evasion mechanism of Trypanosoma brucei?','["T. brucei undergoes antigenic variation of its variable surface glycoprotein (VSG) coat — the genome encodes >1000 VSG gene cassettes; stochastic switching of the single expressed VSG (at the telomeric expression site) at a rate of ~10^-2 per division produces new antigenic variants that outpace host antibody responses, creating waves of parasitaemia"]','A','Only one VSG gene is expressed at a time via monoallelic expression at the active telomeric expression site. Antibody clears the dominant population but pre-existing rare variants with novel VSG proliferate unopposed. T. brucei is entirely EXTRACELLULAR (bloodstream and CSF) — unlike T. cruzi (intracellular). This fundamental difference in biology explains why T. brucei evades CMI responses targeted at intracellular pathogens.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','medium','flashcard','How do Leishmania amastigotes survive within macrophage phagolysosomes?','["Leishmania amastigotes resist lysosomal killing by: surface metalloprotease gp63 (cleaves complement C3b, inhibiting phagocytosis and cleaving signalling proteins); lipophosphoglycan (LPG) inhibiting PKC and phagosome-lysosome fusion; scavenging host purines (cannot synthesise de novo); downregulating macrophage IL-12 and TNF-alpha production to suppress TH1 responses"]','A','Intracellular location protects from antibodies (CMI essential for control). IFN-gamma from TH1 cells activates macrophages to produce NO, which kills amastigotes. TH2 dominance in visceral leishmaniasis correlates with progressive disease. TGF-beta and IL-10 from regulatory T-cells suppress the protective TH1 response — explaining why some individuals develop progressive visceral disease while others self-cure.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','flashcard','What are the histological findings in hepatic amoebic abscess?','["Amoebic liver abscess: ''''anchovy paste'''' or chocolate-brown fluid (NOT true pus — contains lysed hepatocytes and altered blood, essentially bacteria-free). Wall: thin rim of fibrous tissue with viable trophozoites at the periphery containing ingested RBCs (pathognomonic — erythrophagocytosis). MINIMAL inflammatory infiltrate (E. histolytica kills neutrophils via amoebapores)"]','A','CT: typically single, right hepatic lobe (portal vein drainage from ascending colon). Serology (ELISA): >95% sensitive for invasive amoebiasis — differentiates from pyogenic abscess (pus + bacteria + neutrophils). Treatment: metronidazole 5-10 days (kills trophozoites) THEN diloxanide furoate 10 days (luminal agent to eliminate intestinal cysts). Needle drainage only for very large (>10cm), imminent rupture, or no response to metronidazole.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','flashcard','What is onchocerciasis (river blindness) and how does blindness develop?','["Onchocerca volvulus (Simulium blackfly vector, near fast-flowing rivers) → microfilariae in cornea die → repeated cycles of inflammatory keratitis (punctate, then sclerosing) → irreversible corneal scarring → blindness. Skin manifestations: pruritus, ''''leopard skin'''' depigmentation, lichenification, subcutaneous nodules (onchocercomas) containing adult worms"]','A','18 million people infected; second leading cause of preventable infectious blindness globally (after trachoma). Annual ivermectin distribution (kills microfilariae, not adults) is the cornerstone of WHO Onchocerciasis Elimination Programme. Doxycycline kills endosymbiotic Wolbachia bacteria within the worm → adult worm sterilisation and eventual death. Black flies breed near fast-flowing rivers — highest disease burden near river valleys.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Tropical & Neglected Diseases','hard','flashcard','What is the full life cycle of Schistosoma and how does the granulomatous response cause pathology?','["Cercariae penetrate intact human skin → schistosomulae migrate via blood to lungs → adult worms in mesenteric/vesical veins lay eggs → eggs penetrate gut/bladder wall (using proteases) → excreted in stool/urine (infect freshwater snails → cercariae released) → trapped eggs in liver/bladder provoke TH2 eosinophilic granulomas → progressive periovular fibrosis (Symmers fibrosis) + portal hypertension or bladder SCC"]','A','Katayama fever = acute serum sickness-like syndrome during initial heavy infection (immune complexes from massive cercarial/schistosomular antigens). Diagnosis: Kato-Katz stool microscopy for eggs (most specific), serology, or rectal snip biopsy. Treatment: praziquantel (single 40 mg/kg dose, all species). S. mansoni/japonicum → hepatic schistosomiasis; S. haematobium → urogenital schistosomiasis + bladder SCC risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','easy','flashcard','What are the four SIRS criteria?','["SIRS (≥2 required): (1) Temperature >38°C or <36°C; (2) Heart rate >90 bpm; (3) Respiratory rate >20/min OR PaCO2 <32 mmHg; (4) WBC >12,000/µL or <4,000/µL OR >10% immature (band) forms"]','A','SIRS is a non-specific systemic inflammatory response triggered by infection, trauma, burns, or pancreatitis. Sepsis = SIRS + confirmed/suspected infection. The Sepsis-3 (2016) definition replaced SIRS with SOFA score ≥2 for organ dysfunction, which better predicts mortality than SIRS alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','easy','flashcard','What is the Sepsis-3 definition of septic shock?','["Septic shock (Sepsis-3): sepsis WITH persistent hypotension requiring vasopressors to maintain MAP ≥65 mmHg PLUS serum lactate >2 mmol/L despite adequate fluid resuscitation (≥30 mL/kg IV crystalloid) — reflecting both vasodilatory failure and cellular metabolic dysoxia"]','A','Hospital mortality in septic shock exceeds 40%. qSOFA: ≥2 of [altered GCS + RR ≥22 + SBP ≤100] identifies high-risk patients outside ICU. ''''Hour-1 bundle'''': blood cultures before antibiotics, broad-spectrum antibiotics, 30 mL/kg crystalloid, vasopressors if MAP <65, lactate measurement and re-measurement.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','easy','flashcard','What is Waterhouse-Friderichsen syndrome and which organisms classically cause it?','["Bilateral haemorrhagic adrenal infarction causing acute cortisol/aldosterone deficiency, classically complicating Neisseria meningitidis septicaemia with DIC — also caused by Pseudomonas aeruginosa, Streptococcus pneumoniae, and E. coli; clinically presents with purpuric rash, hypotension, and refractory cardiovascular collapse"]','A','DIC-induced haemorrhage destroys both adrenal cortices. Adrenals appear black, swollen, and completely haemorrhagic at autopsy. IV hydrocortisone is life-saving (replaces absent cortisol). Give IV benzylpenicillin BEFORE hospital transfer in suspected meningococcal disease (do not wait for results). Purpuric rash is non-blanching (vascular occlusion/haemorrhage), unlike the blanching rashes of viral exanthems.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','flashcard','What is the cytokine cascade triggered in Gram-negative sepsis?','["LPS activates macrophage TLR4 → early release of TNF-alpha and IL-1 (''''master cytokines'''') → secondary mediators: IL-6, IL-8 (neutrophil recruitment), PAF, prostaglandins, nitric oxide (vasodilation) → fever, hypotension, capillary leak (endothelial activation), DIC (tissue factor expression), and myocardial depression"]','A','TNF-alpha drives DIC by inducing tissue factor on endothelium and inhibiting protein C (anticoagulant). IL-6 drives acute phase response (CRP, fibrinogen, serum amyloid A). High-dose TNF-alpha causes mitochondrial dysfunction and cellular energy failure. Anti-cytokine therapies (anti-TNF, anti-IL-1, anti-IL-6) have largely failed in sepsis RCTs, possibly because the window for intervention is narrow.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','flashcard','What is DIC and what are its laboratory hallmarks?','["Disseminated Intravascular Coagulation: widespread microthrombus formation consumes platelets and clotting factors → paradoxical haemorrhage. Labs: ↓platelets, ↓fibrinogen (<1.5 g/L), ↑PT and ↑APTT, ↑D-dimer (>4 µg/mL FEU), schistocytes on blood film (MAHA from fibrin-strand shearing of RBCs)"]','A','DIC triggers: sepsis (endotoxin + cytokines activate tissue factor), trauma (''''lethal triad'''': hypothermia + acidosis + coagulopathy), obstetric emergencies (amniotic fluid embolism, abruption), APML (azurophilic granules contain procoagulants). Treatment: address the underlying cause first; transfuse FFP + cryoprecipitate + platelets for active bleeding. Heparin rarely used (only in purely thrombotic DIC without bleeding).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','flashcard','What is MAHA and in what infectious conditions does it occur?','["Microangiopathic haemolytic anaemia: mechanical fragmentation of RBCs traversing fibrin microthrombi in small vessels → schistocytes (helmet cells) on blood film + elevated LDH + low haptoglobin + Coombs-negative haemolytic anaemia. Infectious contexts: DIC from any severe sepsis, HUS (EHEC Shiga toxin → glomerular endothelial damage), severe P. falciparum malaria"]','A','Schistocytes are pathognomonic of microangiopathic process (vs immune haemolysis where Coombs is positive and no schistocytes). TTP vs HUS: TTP = severe thrombocytopenia + neurological symptoms + very low ADAMTS13 (<10%); HUS = predominant AKI + preceding diarrhoeal prodrome (EHEC). EHEC-HUS: avoid antibiotics; TTP: urgent plasma exchange + caplacizumab.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','medium','flashcard','What is procalcitonin (PCT) and how is it used in sepsis management?','["PCT (calcitonin precursor) is produced by parenchymal cells (liver, adipocytes, muscle) in response to endotoxin and pro-inflammatory cytokines — rises in bacterial/fungal infection (>0.5 µg/L suggests sepsis; >2 µg/L severe sepsis/shock) but remains LOW in viral infections and localised inflammation (IFN-gamma from activated T-cells suppresses PCT in viral illness)"]','A','PCT-guided antibiotic stewardship in respiratory infections reduces antibiotic duration without worsening outcomes (PRORATA trial). PCT declines rapidly (half-life 24-35 hours) with successful treatment — serial PCT guides de-escalation. Limitations: PCT elevated post-major surgery, trauma, cardiogenic shock, and thyroid medullary carcinoma. SAPS3/SOFA scores better predict mortality than PCT alone.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','flashcard','What is the molecular mechanism by which LPS activates TLR4 signalling?','["LPS (lipid A moiety) binds LBP in serum → LPS-LBP binds CD14 on macrophages → presented to TLR4/MD-2 heterodimer → TLR4 homodimerisation → MyD88/TIRAP adaptor recruitment → IRAK4/TRAF6 → IKK complex → IκB phosphorylation and degradation → NF-κB nuclear translocation → inflammatory gene transcription (TNF-alpha, IL-1, IL-6, IL-12, COX-2, iNOS)"]','A','TLR4 also signals via TRIF/TRAM adaptor (MyD88-independent), activating IRF3 and inducing type I interferons — explaining the antiviral-like component of LPS responses. Monophosphoryl lipid A (MPL) — a detoxified lipid A retaining TH1-adjuvant activity — is used in HPV (Cervarix) and HBV vaccines. Eritoran (TLR4 antagonist) failed in phase III sepsis trials despite promising preclinical data.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','flashcard','What are the organ-specific pathological findings at autopsy in fatal septic shock?','["Lungs: diffuse alveolar damage (ARDS — hyaline membranes, alveolar oedema, type II pneumocyte hyperplasia); Kidneys: acute tubular necrosis; Liver: centrilobular necrosis (hypoperfusion); Adrenals: bilateral haemorrhage; Heart: focal subendocardial necrosis + macrophage infiltrates; Gut: ischaemic enterocolitis; Brain: microabscesses or embolic infarcts"]','A','Pathophysiological sequence: hyperdynamic sepsis (warm shock — high CO, low SVR, warm extremities) → progressive vasodilation + myocardial depression → end-organ hypoperfusion → multi-organ failure. Post-sepsis syndrome: T-cell apoptosis, PD-1/PD-L1 upregulation → prolonged immunosuppression → susceptibility to secondary nosocomial infections and viral reactivation (CMV, HSV, EBV).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Sepsis & Systemic Inflammatory Response','hard','flashcard','What is the role of activated protein C in preventing DIC and why did drotrecogin alfa fail clinically?','["Activated protein C (APC) is an endogenous anticoagulant and anti-inflammatory protein that: cleaves factors Va and VIIIa (dampening thrombin generation); inhibits PAI-1 (promoting fibrinolysis); reduces cytokine production from monocytes. In sepsis, thrombomodulin-thrombin activation of protein C is impaired. Drotrecogin alfa (recombinant APC) reduced 28-day mortality in the PROWESS trial but the PROWESS-SHOCK trial showed no benefit (withdrawn 2011)"]','A','APC has a narrow therapeutic window and causes bleeding (especially in thrombocytopenic patients). The PROWESS failure likely reflects patient selection — APC may benefit only specific high-severity sepsis subgroups. Current sepsis management: source control, early appropriate antibiotics, fluid resuscitation, vasopressors (noradrenaline first-line), and steroid consideration (hydrocortisone + fludrocortisone in vasopressor-dependent septic shock — ADRENAL trial).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','easy','flashcard','What is the mecA gene and how does it confer MRSA resistance?','["mecA (on mobile SCCmec element) encodes PBP2a, an alternative transpeptidase with very low affinity for ALL beta-lactam antibiotics — it substitutes for normal PBPs to continue cell-wall peptidoglycan crosslinking even in the presence of penicillins, cephalosporins, and carbapenems"]','A','Normal PBPs are serine-active-site transpeptidases irreversibly inhibited by beta-lactams (suicide inhibitors). PBP2a has a modified active site with steric hindrance preventing beta-lactam binding. Vancomycin bypasses PBP2a by binding D-Ala-D-Ala peptidoglycan precursors directly. CA-MRSA strains (e.g., USA300) often carry Panton-Valentine leukocidin (PVL) causing necrotising skin infections and necrotising pneumonia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','easy','flashcard','Why is alcohol hand gel ineffective against C. difficile and what should be used instead?','["C. difficile produces heat- and desiccation-resistant endospores NOT destroyed by alcohol — alcohol cannot denature the keratinous spore cortex proteins; soap-and-water handwashing with mechanical friction PHYSICALLY removes spores. Environmental decontamination requires sodium hypochlorite (bleach) 1000-5000 ppm"]','A','C. difficile spores survive on dry surfaces for months. Alcohol gel IS effective for standard bacteria and enveloped viruses but NOT C. difficile, norovirus (non-enveloped), or Cryptosporidium oocysts. Contact precautions (gloves + apron) + single room + soap handwashing + bleach cleaning are the essential infection control triad for CDI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','easy','flashcard','What are the ESKAPE pathogens and why are they clinically important?','["ESKAPE: Enterococcus faecium (VRE), Staphylococcus aureus (MRSA), Klebsiella pneumoniae (ESBL/KPC), Acinetobacter baumannii (CRAB), Pseudomonas aeruginosa (MDR-PA), Enterobacter species (AmpC + ESBL) — responsible for the majority of HAIs with high antimicrobial resistance, limited treatment options, and significant morbidity/mortality"]','A','ESKAPE organisms ''''escape'''' antibiotic killing via: enzymatic degradation (beta-lactamases, carbapenemases), target modification (PBP2a, altered D-Ala-D-Lac), efflux pumps, porin loss, and biofilm formation. WHO Critical Priority Pathogens (carbapenem-resistant): CRAB, CRPA, CRKP + NDM-producing Enterobacteriaceae. These organisms are prioritised for new antibiotic development.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','flashcard','What is the mechanism of vancomycin resistance in VRE?','["VanA/VanB operons (on transposons on conjugative plasmids) encode enzymes that: (1) synthesise D-Ala-D-Lac (or D-Ala-D-Ser in VanC) instead of D-Ala-D-Ala; (2) destroy existing D-Ala-D-Ala-containing precursors. Vancomycin cannot bind D-Ala-D-Lac (loss of 1 of 5 hydrogen bonds → 1000-fold reduction in binding affinity → loss of bactericidal activity)"]','A','VanA: high-level resistance to vancomycin AND teicoplanin (MIC >256 µg/mL); constitutive or inducible. VanB: variable vancomycin resistance ONLY (teicoplanin retains activity). VanC: intrinsic low-level resistance in E. casseliflavus/gallinarum (chromosomal, not transferable). Treatment options: linezolid, daptomycin, tigecycline, tedizolid. VRE colonises the GI tract and is extremely difficult to eradicate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','flashcard','What is KPC and how does it differ from NDM-1 in terms of mechanism and treatment implications?','["KPC (Klebsiella pneumoniae carbapenemase): Class A serine-based enzyme on Tn4401 transposon/plasmid; hydrolyses all beta-lactams including carbapenems; INHIBITED by avibactam (ceftazidime-avibactam is effective). NDM-1 (New Delhi metallo-beta-lactamase): Class B zinc-dependent metalloenzyme on transmissible plasmid; hydrolyses all beta-lactams including carbapenems and aztreonam; NOT inhibited by avibactam — requires aztreonam-avibactam"]','A','KPC: endemic in USA, Italy, Greece, Israel. NDM-1: endemic in South Asia (India, Pakistan), Middle East, spreading globally. Both encoded on mobile plasmids with rapid inter-species spread (E. coli, Klebsiella, Enterobacter, Serratia). Meropenem-vaborbactam is active against KPC but NOT NDM-1. Cefiderocol (siderophore cephalosporin) has activity against KPC, NDM-1, and some OXA carbapenemases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','flashcard','What is pseudomembranous colitis and what are its histological hallmarks?','["Pseudomembranous colitis (C. difficile CDI): yellow-white plaques (pseudomembranes) of fibrin, mucin, neutrophils, and necrotic epithelial cells on inflamed colonic mucosa; histology shows ''''summit lesions'''' (''''volcano lesions'''') — mushroom-shaped eruptions of fibrinopurulent exudate erupting from crypts over focal areas of superficial epithelial necrosis"]','A','Toxin A (enterotoxin): stimulates NF-κB → IL-8 secretion → neutrophil recruitment + fluid secretion. Toxin B (cytotoxin): 10x more potent; glucosylates Rho GTPases (inactivating them) → actin cytoskeletal collapse → cell death. Hypervirulent NAP1/ribotype 027: produces 16-23x more toxin + binary toxin CDT. Treatment: oral vancomycin (125mg QDS × 10 days) or fidaxomicin (superior efficacy, lower recurrence). Bezlotoxumab (anti-toxin B monoclonal) reduces recurrence in high-risk patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','medium','flashcard','What are the NICE infection control requirements for C. difficile in hospital?','["NICE guidance: (1) isolate in single room + contact precautions (gloves + apron) when CDI suspected; (2) soap-and-water handwashing (alcohol gel ineffective against spores); (3) environmental decontamination with sodium hypochlorite 1000-5000 ppm; (4) restrict high-risk antibiotics (clindamycin, 2nd-3rd gen cephalosporins, fluoroquinolones); (5) review PPIs; (6) antimicrobial stewardship programmes"]','A','The 4Cs of CDI prevention: Colonisation resistance (maintain gut microbiome diversity), Contamination control (bleach cleaning), Contact precautions (isolate + PPE), Curtail antibiotics (stewardship). UK CDI rates reduced by >80% since 2007 through mandatory surveillance, antibiotic stewardship, and infection control measures. Faecal microbiota transplant (FMT) is highly effective (>90%) for recurrent CDI.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','flashcard','What resistance mechanisms give Pseudomonas aeruginosa intrinsic multidrug resistance?','["P. aeruginosa intrinsic resistance mechanisms: (1) reduced outer membrane permeability (OprD porin loss → carbapenem resistance); (2) constitutive AmpC beta-lactamase (inducible to high levels); (3) MexAB-OprM efflux pump (expels fluoroquinolones, tetracyclines, beta-lactams); (4) alginate biofilm in CF lungs (mucoid phenotype) rendering the organism effectively untreatable"]','A','Acquired resistance adds: MexXY-OprM efflux pump (aminoglycosides), metallo-beta-lactamases (VIM, IMP — carbapenem resistance), ESBLs. CF patients develop chronic mucoid P. aeruginosa infection that cannot be eradicated — inhaled antibiotics (tobramycin, colistin, aztreonam) maintain suppressive therapy. Active antibiotics: piperacillin-tazobactam, ceftolozane-tazobactam (ESBL+), ceftazidime-avibactam (VIM-negative), colistin (last resort), cefiderocol.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','flashcard','What makes Acinetobacter baumannii a uniquely dangerous nosocomial pathogen?','["A. baumannii has extraordinary environmental persistence (survives on dry surfaces for months — unique among Gram-negatives via desiccation-resistance mechanism), rapidly accumulates resistance genes via class 1 integrons (OXA-23, OXA-48, NDM-1 carbapenemases, efflux pumps MexABC), and can become XDR/PDR causing pneumonia, BSI, and wound infections in ICU patients with limited treatment options"]','A','Intrinsic resistance: chromosomal OXA-51 carbapenemase (low-level). Acquired: OXA-23/OXA-48 (most common), NDM-1, efflux pump overexpression (AdeABC), porin loss. Environmental decontamination: hydrogen peroxide vapour (HPV) or UV-C are highly effective. Treatment of XDR CRAB: colistin + carbapenem (extended-infusion), cefiderocol (siderophore cephalosporin), sulbactam-durlobactam (targets PBP1/PBP3). Nicknamed ''''Iraqibacter'''' after military hospital outbreaks in Iraq.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Healthcare-Associated Infections','hard','flashcard','What is the clinical significance of ESBL-producing Enterobacteriaceae in the community?','["ESBLs (extended-spectrum beta-lactamases, mainly CTX-M-15 in E. coli; TEM, SHV in Klebsiella): hydrolyse all penicillins, 3rd-generation cephalosporins, and aztreonam — but NOT carbapenems; genes on conjugative plasmids commonly co-carrying aminoglycoside/fluoroquinolone resistance genes → virtually pan-oral-antibiotic resistance making community UTI extremely difficult to treat empirically"]','A','ESBL E. coli is the commonest cause of community UTI in many countries (especially after travel to South Asia/Far East). Empirical nitrofurantoin or fosfomycin for uncomplicated ESBL UTI. Ertapenem or meropenem for complicated ESBL infection. ''''Inoculum effect'''': ESBL organisms may appear susceptible to cephalosporins at low inoculum but resistant at high inoculum — clinical failures occur despite susceptible MICs. EUCAST/CLINICAST now recommend reporting ESBL-producing organisms as resistant to all penicillins and cephalosporins regardless of MIC.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','easy','flashcard','What is Pneumocystis jirovecii pneumonia (PCP) and at what CD4 count does it occur in HIV?','["PCP (caused by Pneumocystis jirovecii, a fungus formerly classified as a protozoan) occurs when CD4 <200 cells/µL; presents with progressive dyspnoea on exertion, dry cough, fever, bilateral perihilar ground-glass infiltrates (''''bat-wing'''' pattern) on CT, and markedly elevated serum LDH"]','A','GMS stain: cup-shaped/''''crushed ping-pong ball'''' cysts in BAL. Foamy eosinophilic intra-alveolar exudate on H&E. Treatment: high-dose TMP-SMX × 21 days. Add prednisolone if PaO2 <70 mmHg (reduces mortality by dampening inflammatory response). Prophylaxis: TMP-SMX (also covers Toxoplasma) when CD4 <200. Aerosol pentamidine for TMP-SMX-intolerant patients (does not protect against Toxoplasma).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','easy','flashcard','What is CMV retinitis and what is its characteristic appearance on fundoscopy?','["CMV retinitis (CD4 <50 cells/µL): ''''pizza-pie'''' or ''''cottage cheese and ketchup'''' fundoscopic appearance — white fluffy areas of retinal necrosis interspersed with perivascular haemorrhages along retinal vessel branches; begins in the peripheral retina and progresses centrally toward the macula and optic disc causing irreversible vision loss"]','A','The commonest cause of blindness in advanced AIDS (pre-HAART). Diagnosis: ophthalmoscopy (clinical diagnosis). CMV DNA PCR in blood or aqueous supports diagnosis. Treatment: valganciclovir (oral) for peripheral retinitis; IV ganciclovir for sight-threatening zone 1 disease. Foscarnet or cidofovir for ganciclovir-resistant CMV (UL97 mutation). CMV-IRIS after HAART start can paradoxically worsen retinitis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','easy','flashcard','What are the imaging features of CNS Toxoplasma encephalitis in AIDS?','["Multiple ring-enhancing lesions on contrast CT/MRI (CD4 <100), characteristically involving the basal ganglia and corticomedullary junction with surrounding oedema and mass effect — multiplicity is the hallmark; lesions respond to empirical pyrimethamine + sulfadiazine + folinic acid within 2 weeks"]','A','Multiple ring-enhancing lesions → treat empirically for Toxoplasma (do NOT biopsy first). Single lesion or no response at 14 days → biopsy (consider CNS lymphoma — EBV-driven, thallium SPECT hypermetabolic). Toxoplasma IgG is almost universally positive in symptomatic AIDS patients (reactivation). Primary prophylaxis: TMP-SMX when CD4 <100 (also protects against PCP).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','flashcard','How is Cryptococcal meningitis diagnosed and what are its characteristic CSF findings?','["India ink stain: clear halo (polysaccharide capsule) around narrow-based budding yeast. CrAg lateral flow assay (LFA): >95% sensitive in CSF and serum. CSF: markedly elevated opening pressure (>25 cmH2O, sometimes >60), few or no inflammatory cells (no CMI to recruit leucocytes), low glucose, elevated protein. Culture on Sabouraud agar confirms the species"]','A','Paucicellular CSF paradoxically reflects severity of immunosuppression. Elevated ICP is the leading cause of early mortality — serial therapeutic lumbar punctures (30mL at each, 2×/day initially) are critical; lumbar drain if refractory. WHO guidelines: liposomal amphotericin B + flucytosine × 2 weeks → fluconazole 400mg × 8 weeks → fluconazole 200mg maintenance until CD4 >100 on ART for >3 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','flashcard','What is disseminated Mycobacterium avium complex (MAC) in advanced AIDS?','["Disseminated MAC (CD4 <50 cells/µL): fever, drenching night sweats, profound weight loss, diarrhoea, abdominal pain, hepatosplenomegaly, and pancytopenia; bone marrow and liver biopsies show macrophages packed with AFB (similar to lepromatous leprosy); blood cultures on mycobacterial media (BACTEC Myco/F lytic) are positive in >90% of cases"]','A','MAC is the most common disseminated bacterial infection in advanced AIDS (pre-HAART era). Entry via respiratory/GI tract. Treatment: clarithromycin + ethambutol ± rifabutin × minimum 12 months. Primary prophylaxis: azithromycin 1250mg weekly when CD4 <50 (discontinue when CD4 >100 on sustained ART). MAC-IRIS causes painful cervical or intra-abdominal lymphadenopathy after HAART initiation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','flashcard','What stain identifies Pneumocystis jirovecii cysts and what do they look like?','["GMS (Gomori Methenamine Silver) stain: cysts stain black against a pale green background, appearing as 5-8 µm oval to cup-shaped (''''crushed ping-pong ball'''' or ''''deflated ball'''') structures; intracystic bodies (trophozoites) are identified on Giemsa stain"]','A','Cysts are invisible on standard H&E (foamy alveolar exudate is the clue). BAL is the gold standard specimen (sensitivity >90%). Induced sputum with hypertonic saline has ~50-90% sensitivity. PCR of BAL is most sensitive and specific. The organism cannot be cultured in vitro. Calcofluor white and toluidine blue O are alternative rapid stains for the cyst wall polysaccharides.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','medium','flashcard','What are the prophylaxis strategies for AIDS-defining opportunistic infections?','["CD4 <200: TMP-SMX for PCP (also covers Toxoplasma); CD4 <100: pyrimethamine + dapsone for Toxoplasma if TMP-SMX not tolerated; CD4 <50: azithromycin weekly for MAC; in high-prevalence settings: fluconazole for Cryptococcus. CMV: no routine prophylaxis — screen with fundoscopy every 3 months at CD4 <50"]','A','Primary prophylaxis prevents first episode; secondary prophylaxis (maintenance therapy) prevents recurrence after an episode. Discontinuation thresholds (after sustained ART with adequate CD4 recovery): PCP prophylaxis can stop at CD4 >200; Toxoplasma prophylaxis at CD4 >200; MAC prophylaxis at CD4 >100. Avoid live vaccines when CD4 <200 (risk of disseminated vaccine strain disease).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','flashcard','What is Immune Reconstitution Inflammatory Syndrome (IRIS) and when does it occur?','["IRIS: paradoxical clinical deterioration occurring within weeks-months of starting ART as the recovering immune system mounts an excessive inflammatory response to pre-existing (sometimes subclinical) OIs — two types: (1) Paradoxical IRIS: known OI worsens after ART; (2) Unmasking IRIS: subclinical OI becomes clinically apparent after ART-driven immune restoration"]','A','Commonest IRIS: TB-IRIS (worsening lymphadenopathy, fever, infiltrates 4-8 weeks after ART). Cryptococcal IRIS can cause fatal elevated ICP → serial LP drainage critical. Risk factors: low baseline CD4 + high antigen burden at ART initiation + rapid CD4 rise. Management: continue ART, treat the OI aggressively, prednisolone 1.5 mg/kg × 2 weeks (then taper) for moderate/severe IRIS (NOT cryptococcal — worsens ICP).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','flashcard','How does Toxoplasma gondii cause ring-enhancing brain lesions in AIDS?','["T. gondii tachyzoites infect brain parenchyma → local tissue necrosis + vascular thrombosis → central avascular necrotic core (no contrast uptake). Surrounding active inflammation, reactive angiogenesis, and oedema has disrupted blood-brain barrier → contrast leaks into this inflammatory rim → ring enhancement on CT/MRI. Oedema extends beyond the ring, causing mass effect"]','A','Ring = disrupted BBB at the inflammatory periphery, NOT in the avascular necrotic centre. Multiple lesions reflect haematogenous dissemination of reactivated tachyzoites from tissue cysts. Basal ganglia involvement is typical (highly vascularised, high cyst burden). MRI with gadolinium (FLAIR + DWI) superior to CT. Thallium-201 SPECT or FDG-PET: Toxoplasma = cold/hypometabolic; CNS lymphoma = hot/hypermetabolic.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Immunodeficiency & Opportunistic Infections','hard','flashcard','What is Progressive Multifocal Leukoencephalopathy (PML) and what is its pathogenesis?','["PML (CD4 <100-200 cells/µL): JC virus (polyomavirus) reactivation infects and lyses oligodendrocytes (the myelin-producing cells of the CNS) → progressive demyelination of white matter → personality change, cognitive decline, focal neurological deficits (hemiparesis, aphasia, visual field defects), cerebellar ataxia, seizures, and death within months"]','A','MRI: multifocal white matter T2/FLAIR hyperintensities WITHOUT mass effect, oedema, or contrast enhancement (unlike Toxoplasma or CNS lymphoma). CSF: JC virus PCR >95% specific. No proven antiviral treatment; ART-driven immune reconstitution is the only intervention that can stabilise PML — but risks PML-IRIS. Natalizumab (anti-VLA-4 for MS/Crohn''''s) prevents lymphocyte trafficking into CNS → JC virus surveillance lost → iatrogenic PML in immunocompetent patients.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Mycobacterial Infections','hard','flashcard','What antibiotic regimens are used in standard TB treatment and what is the rationale for four-drug therapy?','["Standard TB treatment: 2-month intensive phase — RIPE (Rifampicin + Isoniazid + Pyrazinamide + Ethambutol) followed by 4-month continuation phase — RI (Rifampicin + Isoniazid); four drugs are used simultaneously to prevent selection of resistant mutants"]','A','The natural mutation rate for single-drug resistance is ~10^-7 to 10^-9 per bacterial division. A pulmonary cavity contains up to 10^9 bacilli — meaning ~10-100 cells are naturally resistant to any single drug. Four-drug combinations reduce the probability of simultaneous resistance to all four drugs to ~10^-28, making selection of multidrug-resistant mutants mathematically near-impossible. MDR-TB = resistant to rifampicin + isoniazid. DOT (directly observed therapy) is essential for adherence and preventing acquired resistance.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — DNA Viruses','medium','flashcard','What distinguishes primary from recurrent HSV infection clinically and virologically?','["Primary HSV: first exposure, no pre-existing immunity — typically more severe (e.g., primary gingivostomatitis in HSV-1, extensive genital ulceration in HSV-2), associated with systemic symptoms (fever, LAD), higher viral shedding. Recurrent HSV: virus reactivates from neuronal latency — milder, shorter, prodromal tingling, lower viral shedding"]','A','HSV establishes latency in sensory ganglia (trigeminal for HSV-1; sacral DRG for HSV-2). Triggers for reactivation: UV light (HSV-1 cold sores), stress, immunosuppression, fever, menstruation. Asymptomatic shedding accounts for most sexual HSV-2 transmission. Aciclovir (inhibits HSV-specific thymidine kinase-activated DNA polymerase) is used for treatment and suppression. Resistance (thymidine kinase mutation) treated with foscarnet.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Viral Infections — RNA Viruses','medium','flashcard','What is the pathogenesis of measles-induced immune suppression after the rash resolves?','["Measles virus infects dendritic cells and T-lymphocytes via SLAM/CD150 and CD46 → profound lymphopenia (CD4 and CD8 T-cell depletion) → months to years of ''''immune amnesia'''' where previously established immunological memory against unrelated pathogens is partially erased, increasing susceptibility to secondary bacterial infections (pneumonia, otitis media, diarrhoea)"]','A','Studies have shown that measles eliminates 11-73% of a child''''s existing antibody repertoire (wiping out memory B-cells). This immune amnesia explains why measles epidemics were followed by waves of childhood mortality from secondary infections. This immunological vulnerability lasts 2-3 years. The indirect protective effect of measles vaccination (preventing immune amnesia in vaccinated communities) may be as important as direct protection against measles itself.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Infectious Diseases','Pathology','Fungal Infections','hard','flashcard','What is the mechanism of action of antifungal drugs and why is Candida resistance to fluconazole increasing?','["Fluconazole (azole): inhibits lanosterol 14-alpha-demethylase (CYP51A1), blocking ergosterol biosynthesis → accumulation of toxic methylated sterols → disrupted fungal membrane function. Resistance mechanisms: ERG11 gene mutations (reduced target affinity), CDR1/CDR2 efflux pump overexpression (MDR), ERG3 mutations (bypasses toxic sterol accumulation)"]','A','Amphotericin B: binds ergosterol directly, forming pores in fungal membrane → ion leakage → cell death; resistance rare (requires ERG mutations replacing ergosterol). Echinocandins (caspofungin, micafungin): inhibit beta-1,3-glucan synthase (FKS1/FKS2 subunit) → cell wall disruption; resistance: FKS hot-spot mutations. Echinocandin-resistant Candida auris is an emerging global threat — also resistant to fluconazole and often amphotericin B, leaving few treatment options.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Clinical Microbiology Made Ridiculously Simple 6th Ed');
